import{_ as e,o,c as t,a2 as r}from"./chunks/framework.DSoq407f.js";const u=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1786505997000}'),l={name:"faq.md"};function i(n,a,h,d,s,q){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="部署相关" tabindex="-1">部署相关 <a class="header-anchor" href="#部署相关" aria-label="Permalink to &quot;部署相关&quot;">​</a></h2><h3 id="q-安装向导提交后提示-授权验证失败-提交参数不完整" tabindex="-1">Q：安装向导提交后提示&quot;授权验证失败，提交参数不完整&quot;？ <a class="header-anchor" href="#q-安装向导提交后提示-授权验证失败-提交参数不完整" aria-label="Permalink to &quot;Q：安装向导提交后提示&quot;授权验证失败，提交参数不完整&quot;？&quot;">​</a></h3><p>授权码为空且自动获取未成功。两种解法：</p><ul><li>在安装向导的授权码字段<strong>手动粘贴</strong>开发商给你的授权码，重新提交。</li><li>或确认你的部署域名已在授权平台（sq.yuafeng.cn）登记。</li></ul><p>详见 <a href="./deploy/authorization">授权激活</a>。</p><h3 id="q-容器起来了-但访问-install-提示-前端构建未找到" tabindex="-1">Q：容器起来了，但访问 <code>/install</code> 提示&quot;前端构建未找到&quot;？ <a class="header-anchor" href="#q-容器起来了-但访问-install-提示-前端构建未找到" aria-label="Permalink to &quot;Q：容器起来了，但访问 `/install` 提示&quot;前端构建未找到&quot;？&quot;">​</a></h3><p>发布包不完整，前端静态文件缺失。重新解压完整发布包，或联系开发商获取完整包。</p><h3 id="q-安装时数据库连不上" tabindex="-1">Q：安装时数据库连不上？ <a class="header-anchor" href="#q-安装时数据库连不上" aria-label="Permalink to &quot;Q：安装时数据库连不上？&quot;">​</a></h3><p>容器内连<strong>宿主机</strong>上的数据库，地址不要填 <code>localhost</code>，用宿主机内网 IP 或 Docker 网关 <code>172.17.0.1</code>。云数据库填 RDS 地址，并确认安全组放行。详见 <a href="./deploy/install#数据库配置">安装向导</a>。</p><h3 id="q-安装成功-但登录管理后台提示-无权限" tabindex="-1">Q：安装成功，但登录管理后台提示&quot;无权限&quot;？ <a class="header-anchor" href="#q-安装成功-但登录管理后台提示-无权限" aria-label="Permalink to &quot;Q：安装成功，但登录管理后台提示&quot;无权限&quot;？&quot;">​</a></h3><p>权限未初始化。通常是安装流程被中断导致。联系平台方或重新走一次安装。</p><h2 id="运行相关" tabindex="-1">运行相关 <a class="header-anchor" href="#运行相关" aria-label="Permalink to &quot;运行相关&quot;">​</a></h2><h3 id="q-机器人收不到消息" tabindex="-1">Q：机器人收不到消息？ <a class="header-anchor" href="#q-机器人收不到消息" aria-label="Permalink to &quot;Q：机器人收不到消息？&quot;">​</a></h3><p>逐项排查：</p><ol><li>适配器是否<strong>启用</strong>、状态在线（<a href="./admin/adapters">适配器集群</a>）。</li><li>平台凭证是否正确、是否过期。</li><li>Webhook 类：回调地址是否填到平台后台、是否 HTTPS 可访问。</li><li>机器人是否<strong>启用</strong>、订阅是否过期。</li><li>看运行日志（<a href="./admin/audit">审计与日志</a>）有没有事件接入。</li></ol><h3 id="q-某个插件不工作" tabindex="-1">Q：某个插件不工作？ <a class="header-anchor" href="#q-某个插件不工作" aria-label="Permalink to &quot;Q：某个插件不工作？&quot;">​</a></h3><ul><li>该插件是否已<strong>绑定</strong>到机器人并<strong>启用</strong>（<a href="./console/bots">机器人管理</a>）。</li><li>插件订阅的事件类型对不对（比如只订阅 <code>message.group</code>，私聊就不会触发）。</li><li>看插件运行日志有没有报错。</li><li>改了插件代码 / 配置后是否重启了插件进程（配置有约 30 秒缓存）。</li></ul><h3 id="q-qq-官方机器人收不到群消息-没-它" tabindex="-1">Q：QQ 官方机器人收不到群消息（没 @它）？ <a class="header-anchor" href="#q-qq-官方机器人收不到群消息-没-它" aria-label="Permalink to &quot;Q：QQ 官方机器人收不到群消息（没 @它）？&quot;">​</a></h3><p>QQ 官方默认只收 @机器人的消息。要收全部消息，在机器人的<strong>适配器设置</strong>里开启「全量消息当作普通群消息处理」。详见 <a href="./xubp/events#关于全量消息">事件类型</a>。</p><h3 id="q-插件发的-markdown-按钮没效果" tabindex="-1">Q：插件发的 Markdown / 按钮没效果？ <a class="header-anchor" href="#q-插件发的-markdown-按钮没效果" aria-label="Permalink to &quot;Q：插件发的 Markdown / 按钮没效果？&quot;">​</a></h3><p>这些是<strong>部分平台</strong>（如 QQ 官方）支持的特性，不是所有平台都支持。在不支持的平台降级为纯文本。详见 <a href="./plugin-dev/messages#markdown-消息">发送消息</a>。</p><h3 id="q-消息发不出去-发送失败" tabindex="-1">Q：消息发不出去 / 发送失败？ <a class="header-anchor" href="#q-消息发不出去-发送失败" aria-label="Permalink to &quot;Q：消息发不出去 / 发送失败？&quot;">​</a></h3><ul><li>检查内容是否触发平台审核（QQ 官方有消息审核）。</li><li>撤回超过 2 分钟会失败（QQ 官方限制）。</li><li>富媒体的 <code>media_url</code> 是否可访问。</li><li>看运行日志的具体错误。</li></ul><h2 id="计费相关" tabindex="-1">计费相关 <a class="header-anchor" href="#计费相关" aria-label="Permalink to &quot;计费相关&quot;">​</a></h2><h3 id="q-订阅过期了-我的数据和插件还在吗" tabindex="-1">Q：订阅过期了，我的数据和插件还在吗？ <a class="header-anchor" href="#q-订阅过期了-我的数据和插件还在吗" aria-label="Permalink to &quot;Q：订阅过期了，我的数据和插件还在吗？&quot;">​</a></h3><p>在。过期只是<strong>降级</strong>（机器人 / 插件停用），<strong>不删数据</strong>。续费后立即恢复。</p><h3 id="q-余额充值没到账" tabindex="-1">Q：余额充值没到账？ <a class="header-anchor" href="#q-余额充值没到账" aria-label="Permalink to &quot;Q：余额充值没到账？&quot;">​</a></h3><p>支付回调可能有延迟。如果长时间未到账，联系平台方核对订单（提供支付凭证）。</p><h3 id="q-卡密兑换失败" tabindex="-1">Q：卡密兑换失败？ <a class="header-anchor" href="#q-卡密兑换失败" aria-label="Permalink to &quot;Q：卡密兑换失败？&quot;">​</a></h3><ul><li>卡密是否已过期 / 已使用。</li><li>卡密类型是否匹配（套餐卡不能当余额卡用）。</li><li>确认卡密复制完整（无多余空格）。</li></ul><h2 id="开发相关" tabindex="-1">开发相关 <a class="header-anchor" href="#开发相关" aria-label="Permalink to &quot;开发相关&quot;">​</a></h2><h3 id="q-插件上传后看不到" tabindex="-1">Q：插件上传后看不到？ <a class="header-anchor" href="#q-插件上传后看不到" aria-label="Permalink to &quot;Q：插件上传后看不到？&quot;">​</a></h3><p>新插件默认 <code>allow_purchase: false</code>（不上架）。在控制台 / 开发者中心确认上架状态。市场插件还需平台<a href="./admin/marketplace">审核</a>。</p><h3 id="q-改了-main-py-不生效" tabindex="-1">Q：改了 main.py 不生效？ <a class="header-anchor" href="#q-改了-main-py-不生效" aria-label="Permalink to &quot;Q：改了 main.py 不生效？&quot;">​</a></h3><p>插件代码在进程启动时加载，改完要<strong>重启插件进程</strong>才生效。配置（setting.json）改完有约 30 秒缓存延迟。</p><h3 id="q-插件数据怎么存-需要自己建表吗" tabindex="-1">Q：插件数据怎么存？需要自己建表吗？ <a class="header-anchor" href="#q-插件数据怎么存-需要自己建表吗" aria-label="Permalink to &quot;Q：插件数据怎么存？需要自己建表吗？&quot;">​</a></h3><p>不用。用 <code>context.data_store</code> 的键值接口，数据按 <code>插件 + 用户 + 机器人</code> 自动隔离。详见 <a href="./plugin-dev/data-store">数据存储</a>。</p><h3 id="q-怎么让插件在所有平台通用" tabindex="-1">Q：怎么让插件在所有平台通用？ <a class="header-anchor" href="#q-怎么让插件在所有平台通用" aria-label="Permalink to &quot;Q：怎么让插件在所有平台通用？&quot;">​</a></h3><p>用 <code>context.reply()</code>、<code>context.sender_id</code>、<code>context.chat_id</code> 等统一接口，不要直接读平台原始字段。详见 <a href="./plugin-dev/cross-platform">跨平台开发</a>。</p><hr><p>没找到答案？联系平台方或看 <a href="./deploy/ops#故障排查">运维与故障排查</a>。</p>',42)])])}const p=e(l,[["render",i]]);export{u as __pageData,p as default};
